def Erdos1122.HasBoundedDyadicShellOscillation (f : Nat → Real) (C : Real) : Prop :=
  fun f C =>
  ∀ (u : Nat), LE.le 1 u → ∀ (q : Nat), LE.le u q → LE.le q (HMul.hMul 2 u) → LE.le (abs (HSub.hSub (f q) (f u))) C

def Erdos1122.IsCoprimeAdditive (f : Nat → Real) : Prop :=
  fun f =>
  ∀ (a : Nat), GT.gt a 0 → ∀ (b : Nat), GT.gt b 0 → Nat.Coprime a b → Eq (f (HMul.hMul a b)) (HAdd.hAdd (f a) (f b))

theorem Erdos1122.Core.coprime_additive_mul_of_isLittleO_diff {f : Nat → Real} (hf : Erdos1122.IsCoprimeAdditive f)
  (ho : Asymptotics.IsLittleO Filter.atTop (fun n => HSub.hSub (f (HAdd.hAdd n 1)) (f n)) fun x => 1) {a b : Nat}
  (ha : LE.le 1 a) (hb : LE.le 1 b) : Eq (f (HMul.hMul a b)) (HAdd.hAdd (f a) (f b))

theorem Erdos1122.Core.coprime_additive_mul_of_isLittleO_descentCount_of_hasBoundedDownwardJumps {f : Nat → Real}
  (hf : Erdos1122.IsCoprimeAdditive f)
  (ho : Asymptotics.IsLittleO Filter.atTop (fun X => ↑(Erdos1122.descentCount f X)) fun X => ↑X) {D : Real}
  (hD : Erdos1122.HasBoundedDownwardJumps f D) {a b : Nat} (ha : LE.le 1 a) (hb : LE.le 1 b) :
  Eq (f (HMul.hMul a b)) (HAdd.hAdd (f a) (f b))

theorem Erdos1122.Core.completely_additive_dyadic_shell_complement_eq {f : Nat → Real}
  (hmul : ∀ (x : Nat), GE.ge x 1 → ∀ (y : Nat), GE.ge y 1 → Eq (f (HMul.hMul x y)) (HAdd.hAdd (f x) (f y))) {u : Nat}
  (hu : LE.le 1 u) (q : Nat) : Eq (HAdd.hAdd (HSub.hSub (f q) (f u)) (HSub.hSub (f (HMul.hMul 2 u)) (f q))) (f 2)

theorem Erdos1122.Core.completely_additive_pow_two_shell_oscillation_of_hasBoundedDyadicShellOscillation {f : Nat → Real}
  (hmul : ∀ (x : Nat), GE.ge x 1 → ∀ (y : Nat), GE.ge y 1 → Eq (f (HMul.hMul x y)) (HAdd.hAdd (f x) (f y))) {C : Real}
  (hC : Erdos1122.HasBoundedDyadicShellOscillation f C) (s : Nat) {u q : Nat} (hu : LE.le 1 u)
  (hlow : LE.le (HMul.hMul (HPow.hPow 2 s) u) q) (hhigh : LE.le q (HMul.hMul (HPow.hPow 2 (HAdd.hAdd s 1)) u)) :
  And (LE.le (abs (HSub.hSub (HSub.hSub (f q) (f u)) (HMul.hMul (↑s) (f 2)))) C)
    (LE.le (abs (HSub.hSub (f q) (f u))) (HAdd.hAdd C (HMul.hMul (↑s) (abs (f 2)))))
